#!/usr/bin/env python3
"""
Enhanced FJSSP Solver with multiple scheduling strategies per machine assignment.
Tries different operation orderings (not just greedy earliest-start).
"""

import json
import csv
import itertools
from copy import deepcopy

# ============================================================
# Problem Data
# ============================================================
num_jobs = 4
num_machines = 3
num_ops_per_job = 3

jobs = [
    [[(0, 6), (1, 5)], [(1, 7), (2, 6)], [(0, 5), (2, 8)]],
    [[(0, 5), (2, 7)], [(1, 6), (2, 5)], [(0, 7), (1, 8)]],
    [[(1, 4), (2, 6)], [(0, 8), (1, 7)], [(0, 6), (2, 5)]],
    [[(0, 7), (1, 6)], [(1, 5), (2, 7)], [(0, 4), (2, 6)]],
]

downtime = {1: [(5, 20)], 2: [(12, 25)]}
baseline = [
    {"job": 1, "op": 0, "machine": 0, "start": 0,  "end": 5,  "dur": 5},
    {"job": 0, "op": 0, "machine": 1, "start": 0,  "end": 5,  "dur": 5},
    {"job": 3, "op": 0, "machine": 0, "start": 5,  "end": 12, "dur": 7},
    {"job": 2, "op": 0, "machine": 1, "start": 5,  "end": 9,  "dur": 4},
    {"job": 0, "op": 1, "machine": 2, "start": 5,  "end": 11, "dur": 6},
    {"job": 1, "op": 1, "machine": 1, "start": 9,  "end": 15, "dur": 6},
    {"job": 2, "op": 2, "machine": 2, "start": 11, "end": 16, "dur": 5},
    {"job": 3, "op": 1, "machine": 1, "start": 15, "end": 20, "dur": 5},
    {"job": 2, "op": 1, "machine": 0, "start": 16, "end": 24, "dur": 8},
    {"job": 3, "op": 2, "machine": 2, "start": 20, "end": 26, "dur": 6},
    {"job": 0, "op": 2, "machine": 0, "start": 24, "end": 29, "dur": 5},
    {"job": 1, "op": 2, "machine": 0, "start": 29, "end": 36, "dur": 7},
]
baseline_makespan = 36

baseline_lookup = {}
for entry in baseline:
    baseline_lookup[(entry["job"], entry["op"])] = entry

freeze_until = 6
frozen_ops = set()
for entry in baseline:
    if entry["start"] < freeze_until:
        frozen_ops.add((entry["job"], entry["op"]))

max_machine_changes = 4
max_total_start_shift_L1 = 120
max_makespan = 39

non_frozen_ops = []
for j in range(num_jobs):
    for k in range(num_ops_per_job):
        if (j, k) not in frozen_ops:
            non_frozen_ops.append((j, k))

alt_choices = {}
for j, k in non_frozen_ops:
    alt_choices[(j, k)] = jobs[j][k]

def overlaps_downtime(machine, start, end):
    if machine not in downtime:
        return False
    for ds, de in downtime[machine]:
        if start < de and end > ds:
            return True
    return False

def find_earliest_slot(timeline, earliest, duration, machine):
    start = earliest
    for _ in range(200):
        end = start + duration
        conflict = False
        if machine in downtime:
            for ds, de in downtime[machine]:
                if start < de and end > ds:
                    start = de
                    conflict = True
                    break
        if conflict:
            continue
        conflict = False
        for ts, te in timeline:
            if start < te and end > ts:
                start = te
                conflict = True
                break
        if conflict:
            continue
        return start
    return start

def validate_schedule(schedule):
    errors = []
    for entry in schedule:
        key = (entry["job"], entry["op"])
        if key in frozen_ops:
            bl = baseline_lookup[key]
            if entry["machine"] != bl["machine"] or entry["start"] != bl["start"] or entry["end"] != bl["end"]:
                errors.append(f"Frozen op {key} was changed")

    job_ops = {}
    for entry in schedule:
        job_ops.setdefault(entry["job"], {})[entry["op"]] = entry
    for j in range(num_jobs):
        for k in range(num_ops_per_job - 1):
            if job_ops[j][k]["end"] > job_ops[j][k+1]["start"]:
                errors.append(f"Precedence: J{j}O{k}")

    for entry in schedule:
        j, k, m, d = entry["job"], entry["op"], entry["machine"], entry["dur"]
        if (m, d) not in jobs[j][k]:
            errors.append(f"Invalid machine/dur: J{j}O{k}")

    machine_ops = {}
    for entry in schedule:
        machine_ops.setdefault(entry["machine"], []).append(entry)
    for m, ops in machine_ops.items():
        ops_sorted = sorted(ops, key=lambda x: x["start"])
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i]["end"] > ops_sorted[i+1]["start"]:
                errors.append(f"Overlap M{m}")

    for entry in schedule:
        key = (entry["job"], entry["op"])
        if key not in frozen_ops:
            if overlaps_downtime(entry["machine"], entry["start"], entry["end"]):
                errors.append(f"Downtime violation: J{entry['job']}O{entry['op']}")

    machine_changes = 0
    for entry in schedule:
        key = (entry["job"], entry["op"])
        bl = baseline_lookup[key]
        if entry["machine"] != bl["machine"]:
            machine_changes += 1
    if machine_changes > max_machine_changes:
        errors.append(f"Machine changes: {machine_changes}")

    total_shift = 0
    for entry in schedule:
        key = (entry["job"], entry["op"])
        bl = baseline_lookup[key]
        total_shift += abs(entry["start"] - bl["start"])
    if total_shift > max_total_start_shift_L1:
        errors.append(f"Shift L1: {total_shift}")

    makespan = max(e["end"] for e in schedule)
    if makespan > max_makespan:
        errors.append(f"Makespan: {makespan}")

    return len(errors) == 0, errors, makespan, machine_changes, total_shift

def schedule_with_priority(assignments, priority_func):
    """Schedule with a custom priority function for selecting next operation."""
    job_available = {j: 0 for j in range(num_jobs)}
    schedule = []
    machine_timeline = {m: [] for m in range(num_machines)}

    # Place frozen operations
    for j, k in sorted(frozen_ops):
        bl = baseline_lookup[(j, k)]
        entry = {"job": bl["job"], "op": bl["op"], "machine": bl["machine"],
                 "start": bl["start"], "end": bl["end"], "dur": bl["dur"]}
        schedule.append(entry)
        machine_timeline[bl["machine"]].append((bl["start"], bl["end"]))
        if bl["end"] > job_available[j]:
            job_available[j] = bl["end"]

    for m in machine_timeline:
        machine_timeline[m].sort()

    remaining = set(non_frozen_ops)
    scheduled_ops = set(frozen_ops)

    while remaining:
        candidates = []
        for j, k in remaining:
            if k > 0 and (j, k-1) not in scheduled_ops:
                continue
            m, d = assignments[(j, k)]
            earliest = job_available[j]
            start = find_earliest_slot(machine_timeline[m], earliest, d, m)
            candidates.append((j, k, m, d, start))

        if not candidates:
            return None

        # Use priority function to select
        candidates.sort(key=priority_func)
        j, k, m, d, start = candidates[0]
        end = start + d

        entry = {"job": j, "op": k, "machine": m, "start": start, "end": end, "dur": d}
        schedule.append(entry)
        machine_timeline[m].append((start, end))
        machine_timeline[m].sort()
        job_available[j] = end
        remaining.remove((j, k))
        scheduled_ops.add((j, k))

    return schedule

# Priority functions
def earliest_start(x):
    return (x[4], x[3])  # earliest start, then shortest duration

def shortest_processing(x):
    return (x[3], x[4])  # shortest processing time first

def earliest_end(x):
    return (x[4] + x[3], x[4])  # earliest end time

def longest_remaining(x):
    j = x[0]
    # Remaining processing time for this job
    remaining = 0
    for kk in range(x[1], num_ops_per_job):
        remaining += min(d for m, d in jobs[j][kk])
    return (-remaining, x[4])  # longest remaining first

priority_funcs = [earliest_start, shortest_processing, earliest_end, longest_remaining]

best_schedule = None
best_makespan = float('inf')
best_info = None

alt_lists = [alt_choices[(j, k)] for j, k in non_frozen_ops]

for combo in itertools.product(*alt_lists):
    assignments = {}
    for j, k in frozen_ops:
        bl = baseline_lookup[(j, k)]
        assignments[(j, k)] = (bl["machine"], bl["dur"])

    machine_changes = 0
    for idx, (j, k) in enumerate(non_frozen_ops):
        m, d = combo[idx]
        assignments[(j, k)] = (m, d)
        bl = baseline_lookup[(j, k)]
        if m != bl["machine"]:
            machine_changes += 1

    if machine_changes > max_machine_changes:
        continue

    for pf in priority_funcs:
        sched = schedule_with_priority(assignments, pf)
        if sched is None:
            continue

        valid, errors, makespan, mc, total_shift = validate_schedule(sched)
        if valid and makespan < best_makespan:
            best_schedule = deepcopy(sched)
            best_makespan = makespan
            best_info = {"machine_changes": mc, "total_shift": total_shift, "pf": pf.__name__}
            print(f"New best: makespan={makespan}, mc={mc}, shift={total_shift}, pf={pf.__name__}, combo={combo}")

print(f"\nBest makespan: {best_makespan}")
print(f"Best info: {best_info}")

if best_schedule:
    best_schedule.sort(key=lambda x: (x["start"], x["job"], x["op"]))
    valid, errors, makespan, mc, total_shift = validate_schedule(best_schedule)
    print(f"\nFinal validation: valid={valid}")
    if errors:
        for e in errors:
            print(f"  ERROR: {e}")
    print(f"Makespan: {makespan}, MC: {mc}, Shift: {total_shift}")

    print("\nSchedule:")
    for entry in best_schedule:
        print(f"  Job {entry['job']} Op {entry['op']}: M{entry['machine']} [{entry['start']}, {entry['end']}) dur={entry['dur']}")

    # Save
    import os
    os.makedirs("/app/output", exist_ok=True)

    solution = {
        "status": "OPTIMIZED",
        "makespan": best_makespan,
        "schedule": best_schedule
    }
    with open("/app/output/solution.json", "w") as f:
        json.dump(solution, f, indent=2)
    print("\nSaved /app/output/solution.json")

    with open("/app/output/schedule.csv", "w", newline='') as f:
        writer = csv.DictWriter(f, fieldnames=["job", "op", "machine", "start", "end", "dur"])
        writer.writeheader()
        for entry in best_schedule:
            writer.writerow(entry)
    print("Saved /app/output/schedule.csv")

