            key = (entry["job"], entry["op"])
            bl = baseline_lookup[key]
            if entry["machine"] != bl["machine"]:
                mc += 1
            total_shift += abs(entry["start"] - bl["start"])

        if mc > max_machine_changes or total_shift > max_total_start_shift_L1:
            continue

        all_solutions.append((makespan, mc, total_shift, deepcopy(sched)))

print(f"Found {len(all_solutions)} feasible solutions")

if all_solutions:
    # Sort by makespan, then mc, then shift
    all_solutions.sort(key=lambda x: (x[0], x[1], x[2]))

    # Show distribution
    from collections import Counter
    makespan_counts = Counter(s[0] for s in all_solutions)
    print(f"Makespan distribution: {dict(sorted(makespan_counts.items()))}")

    best = all_solutions[0]
    print(f"\nBest solution: makespan={best[0]}, mc={best[1]}, shift={best[2]}")

    best_schedule = best[3]
    best_schedule.sort(key=lambda x: (x["start"], x["job"], x["op"]))

    print("\nSchedule:")
    for entry in best_schedule:
        print(f"  Job {entry['job']} Op {entry['op']}: M{entry['machine']} [{entry['start']}, {entry['end']}) dur={entry['dur']}")

    # Save
    import os
    os.makedirs("/app/output", exist_ok=True)

    solution = {
        "status": "OPTIMIZED",
        "makespan": best[0],
        "schedule": best_schedule
    }
    with open("/app/output/solution.json", "w") as f:
        json.dump(solution, f, indent=2)

    with open("/app/output/schedule.csv", "w", newline='') as f:
        writer = csv.DictWriter(f, fieldnames=["job", "op", "machine", "start", "end", "dur"])
        writer.writeheader()
        for entry in best_schedule:
            writer.writerow(entry)

    print("\nSaved solution.json and schedule.csv")
